    private val parsed = HashMap<String, FloatArray>()
    private val circle: FloatArray by lazy {
        FloatArray(360) { i ->
            val a = Math.PI * 2 * (i / 2) / 180.0 - Math.PI / 2
            (0.5 + 0.5 * if (i % 2 == 0) Math.cos(a) else Math.sin(a)).toFloat()
        }
    }
    private val path = Path()

    /** normalized 0..1 outline: x0, y0, x1, y1, … (180 points) */
    @JvmStatic
    fun points(key: String): FloatArray? {
        if (key == CIRCLE) return circle
        parsed[key]?.let { return it }
        val raw = DATA[key] ?: return null
        val parts = raw.split(' ')
        val out = FloatArray(parts.size) { parts[it].toFloat() / 1000f }
        parsed[key] = out
        return out
    }

    @JvmStatic
    fun current(): String = InuConfig.AVATAR_SHAPE.value

    @JvmStatic
    fun isActive(): Boolean {
        val k = current()
        return k != CIRCLE && DATA.containsKey(k)
    }

    /** smooth closed path through the outline: quadratic curves between edge midpoints */
    @JvmStatic
    fun buildPath(out: Path, pts: FloatArray, left: Float, top: Float, width: Float, height: Float) {
        out.rewind()
        val n = pts.size / 2
        if (n < 3) return
        fun x(i: Int) = left + pts[(i % n) * 2] * width
        fun y(i: Int) = top + pts[(i % n) * 2 + 1] * height
        out.moveTo((x(0) + x(1)) / 2f, (y(0) + y(1)) / 2f)
        for (i in 1..n) {
            out.quadTo(x(i), y(i), (x(i) + x(i + 1)) / 2f, (y(i) + y(i + 1)) / 2f)
        }
        out.close()
    }

    /** outline between two shapes, t = 0..1 (values outside overshoot, for springs) */
    @JvmStatic
    fun morph(a: FloatArray, b: FloatArray, t: Float, into: FloatArray) {
        val n = minOf(a.size, b.size, into.size)
        for (i in 0 until n) into[i] = a[i] + (b[i] - a[i]) * t
    }

    private fun isCircular(w: Float, h: Float, radius: Float): Boolean =
        w > 0f && h > 0f && Math.abs(w - h) < 2f && radius >= Math.min(w, h) / 2f - 2f

    /** ImageReceiver hook: returns true when the avatar was drawn as a shape */
    @JvmStatic
    fun drawShaped(canvas: Canvas?, rect: RectF, radius: Int, paint: Paint): Boolean {
        if (canvas == null || !isActive()) return false
        val w = rect.width()
        val h = rect.height()
        if (!isCircular(w, h, radius.toFloat())) return false
        val pts = points(current()) ?: return false
        buildPath(path, pts, rect.left, rect.top, w, h)
        canvas.drawPath(path, paint)
        return true
    }

    /** AvatarDrawable hook (canvas already translated to the avatar's top-left) */
    @JvmStatic
    fun drawBackground(canvas: Canvas, size: Float, paint: Paint): Boolean {
        if (!isActive() || size <= 0f) return false
        val pts = points(current()) ?: return false
        buildPath(path, pts, 0f, 0f, size, size)
        canvas.drawPath(path, paint)
        return true
    }
